import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"开发 TikTools","description":"","frontmatter":{"title":"开发 TikTools","docId":"developer.overview","translationKey":"developer.overview","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"cfa06c11d3c238ac914b0a3a6c2a65881a85b3ad8e6f5a14b7074c4973d4d8c8","translationRevision":"ef4222d10be52ac178ecc1ec052aad03497d14508280762e01fe3afe1267d951","order":0},"headers":[],"relativePath":"zh/developer/index.md","filePath":"zh/developer/index.md","lastUpdated":1795735295000}`),a={name:`zh/developer/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="develop-tiktools" tabindex="-1">开发 TikTools <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to “开发 TikTools”">​</a></h1><p>TikTools 在类型化控制操作背后维护单个原生 AppCore。Vue 渲染桌面、本地浏览器和控制端界面；Winit/Wry 管理桌面窗口。CLI 与 SDK 使用相同操作。先阅读<a href="./setup.html">开发环境设置</a>，再选择能够覆盖改动的最小开发循环。</p><h2 id="choose-an-entry-point" tabindex="-1">选择入口 <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to “选择入口”">​</a></h2><table tabindex="0"><thead><tr><th>工作</th><th>入口</th><th>验证范围</th></tr></thead><tbody><tr><td>Vue 组件与 store</td><td>Vite、Vitest 及注入的 ControlClient</td><td>界面行为；不验证原生窗口。</td></tr><tr><td>桌面集成</td><td><code>bun run start</code></td><td>开发 WebView 与 IPC 集成。</td></tr><tr><td>原生服务</td><td>针对性 Cargo 测试</td><td>核心契约、持久化及服务行为。</td></tr><tr><td>无界面浏览器访问</td><td><code>bun run dev</code></td><td>原生宿主、本地适配器及带配对的 Vite。</td></tr><tr><td>文档</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown、VitePress 以及用于内嵌示例的 demo 开发服务器。</td></tr><tr><td>公开演示</td><td>独立演示入口及模拟传输</td><td>虚构且确定的场景，不验证上游服务。</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">源码职责 <a class="header-anchor" href="#source-ownership" aria-label="Permalink to “源码职责”">​</a></h2><ul><li><code>crates/tiktools-core</code>：服务、操作和 SQLite，不依赖 WebView。</li><li><code>crates/tiktools-control-api</code>：注册表、JSON-RPC 路由、IPC 及发现。</li><li><code>crates/tiktools-desktop</code>：Winit/Wry、UI 线程桥接、生命周期及打包资源。</li><li><code>src/web/app</code>：引导、路由及外壳。<code>pages</code> 组合 <code>widgets</code> 和 <code>features</code>；<code>entities</code> 管理领域 store/契约；<code>shared</code> 包含可复用 UI 和基础设施。</li><li><code>src/automation/contracts/generated</code>：从 Rust 生成的版本化前端事件契约。不要在演示或指南中重新手写这些 schema。</li><li><code>packages</code>：现有 TypeScript 插件 SDK/UI 包。插件实现位于外部插件仓库。</li></ul><h2 id="contribution-boundary" tabindex="-1">贡献边界 <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to “贡献边界”">​</a></h2><p>保持原生、本地浏览器、远程控制端及演示入口明确。真实入口缺少原生宿主时应报错，不能静默选择模拟对象。监听器、订阅和定时器应随所属作用域释放。保持 Rust/Bun 锁文件和必需 CI 门控完整。</p><p>用户安装请参阅<a href="./../user/installation.html">用户指南</a>。这些开发检查本身不能证明真实 TikTok 连接、OBS 渲染、原生 WebView 兼容性或双电脑协作正常。</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};